const int N = 120;



ll t , q , x , y , cntBalls[N][N];



bool solve(ll b , int x , int y)

{

    //If there are b balls generated before the current ball, then there are b balls passed through (0,0)

    //and ceil(b/2) passed through (0,1), and floor(b/2) passed through (1,0)

    //generally, the balls passed through (x,y) is ceil(passed through(x,y-1) / 2) + floor(passed through(x-1,y)/2)



    cntBalls[0][0] = b;

    for(int i=0; i<N; i++)

    {

        for(int j=0; j<N; j++)

        {

            if (!i && !j) continue;

            cntBalls[i][j] = 0;

            if (i) cntBalls[i][j] += (cntBalls[i-1][j]/2);

            if (j) cntBalls[i][j] += (cntBalls[i][j-1]+1)/2;

        }

    }



    //now we can get the direction of each cell

    //cntBalls[i][j] is the number of balls passed through the cell(i,j) from [0,t-1] (number of balls that got out from the cell)



    int i = 0 , j = 0 , tim = x + y;

    while(tim--)

    {

        if (cntBalls[i][j]%2) i++;

        else j++;

    }



    return i == x && j == y;

}



int main()

{

    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);



    cin >> q;

    while(q--)

    {

        cin >> t >> x >> y;



        if (t - x - y < 0) cout << "NO\n";

        else

        {

            //the ball at the cell (x,y) at time t, must be generated at cell(0,0) at time (t-x-y)

            //calculate the directions for each cell to know the path of the ball generated at time(t-x-y)

            if (solve(t - x - y , x , y)) cout << "YES\n";

            else cout << "NO\n";

        }

    }



    return 0;

}

