#include <bits/stdc++.h>
using namespace std;

#define sz(v) int(v.size())
#define ar array
typedef long long ll;
const int N = 2e5+10, MOD = 998244353;

struct T {
    vector<ar<ll, 4>> pre, suf; // {x, mx, sum, len}
    ll mx, sum;
    int len, ans = 0;

    T(): pre(), suf() {}
    T(ll x): pre(), suf() {
        pre.push_back({x, 0, 0, 0});
        pre.push_back({0, x, x, 1});
        suf.push_back({x, 0, 0, 0});
        suf.push_back({0, x, x, 1});
        mx = sum = x;
        len = 1;
    }
} t[4 * N];

int f(const vector<ar<ll, 4>>& one, const vector<ar<ll, 4>>& two) {
    int j = 0;
    int ans = 0;
    for (int i = 0; i < sz(one); i++) {
        while (j+1 < sz(two) && two[j+1][1] <= one[i][1]) j++;
        if (j < sz(two) && two[j][1] <= one[i][1]) {
            if (one[i][1] * 2 < one[i][2] + two[j][2]) {
                ans = max(ans, int(one[i][3] + two[j][3]));
            }
        }
    }
    return ans;
}

T operator + (const T& l, const T& r) {
    T res;
    res.pre = l.pre;
    res.pre.pop_back();

    for (auto [x, mx, sum, len] : r.pre)
        if (x >= sum + l.sum || len == r.len)
            res.pre.push_back({x, max(mx, l.mx), sum + l.sum, len + l.len});

    res.suf = r.suf;
    res.suf.pop_back();
    for (auto [x, mx, sum, len] : l.suf)
        if (x >= sum + r.sum || len == l.len)
            res.suf.push_back({x, max(mx, r.mx), sum + r.sum, len + r.len});

    res.mx = max(l.mx, r.mx);
    res.sum = l.sum + r.sum;
    res.len = l.len + r.len;
    res.ans = max({l.ans, r.ans, f(l.suf, r.pre), f(r.pre, l.suf)});
    return res;
}

int n, q;
ll a[N];

void build(int v, int tl, int tr) {
    if (tl == tr) t[v] = T(a[tl]);
    else {
        int tm = (tl + tr) / 2;
        build(2*v, tl, tm), build(2*v+1, tm+1, tr);
        t[v] = t[2*v] + t[2*v+1];
        /*
        cerr << "> " << tl << ' ' << tr << ' ' << t[v].ans << endl;
        cerr << "pre\n";
        for (auto [x, mx, sum, len] : t[v].pre)
            cerr << "here: " << x << ' ' << mx << ' ' << sum << ' ' << len << endl;
        cerr << "suf\n";
        for (auto [x, mx, sum, len] : t[v].suf)
            cerr << "here: " << x << ' ' << mx << ' ' << sum << ' ' << len << endl;
        cerr << endl;
        */
    }
}

void upd(int v, int tl, int tr, int pos, ll x) {
    if (pos < tl || pos > tr) return;
    if (tl == tr) {
        t[v] = T(x);
        return;
    }
    int tm = (tl + tr) / 2;
    upd(2*v, tl, tm, pos, x), upd(2*v+1, tm+1, tr, pos, x);
    t[v] = t[2*v] + t[2*v+1];
}

T qry(int v, int tl, int tr, int l, int r) {
    if (l <= tl && tr <= r) return t[v];
    int tm = (tl + tr) / 2;
    if (r <= tm) return qry(2*v, tl, tm, l, r);
    else if (tm < l) return qry(2*v+1, tm+1, tr, l, r);
    else return qry(2*v, tl, tm, l, r) + qry(2*v+1, tm+1, tr, l, r);
}

void solve() {
    cin >> n >> q;
    for (int i = 0; i < n; i++) cin >> a[i];

    build(1, 0, n-1);
    while (q--) {
        int t; cin >> t;
        if (t == 1) {
            int l, r; cin >> l >> r, --l, --r;
            int ans = qry(1, 0, n-1, l, r).ans;
            cout << (ans >= 3 ? ans : -1) << '\n';
        } else {
            int i; ll x; cin >> i >> x, --i;
            upd(1, 0, n-1, i, x);
        }
    }
}


int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int T = 1;
    cin >> T;
    while (T--) solve();
}

