struct MATRIX
{
    long long a[30][30];
};

const int p = 1000000007;
int m, n, q;
long long board[50], occ[50], tmpboard[50];
MATRIX trans;

MATRIX fast_pow(MATRIX A, int t)
{
    if (t == 1)
        return A;
    else
    {
        MATRIX T = fast_pow(A, t / 2), S;
        for (int i = 1; i <= n * m; i++)
            for (int j = 1; j <= n * m; j++)
            {
                S.a[i][j] = 0;
                for (int k = 1; k <= n * m; k++)
                    S.a[i][j] = (S.a[i][j] + T.a[i][k] * T.a[k][j]) % p;
            }
        if (t % 2 == 1)
        {
            MATRIX S1;
            for (int i = 1; i <= n * m; i++)
                for (int j = 1; j <= n * m; j++)
                {
                    S1.a[i][j] = 0;
                    for (int k = 1; k <= n * m; k++)
                        S1.a[i][j] = (S1.a[i][j] + S.a[i][k] * A.a[k][j]) % p;
                }
            return S1;
        }
        else
            return S;
    }
}

void calculate_now(int t)
{
    if (t == 0)
        return;
    MATRIX S = fast_pow(trans, t);
    for (int i = 1; i <= n * m; i++)
    {
        tmpboard[i] = 0;
        for (int k = 1; k <= n * m; k++)
            tmpboard[i] = (tmpboard[i] + board[k] * S.a[k][i]) % p;
    }
    for (int i = 1; i <= n * m; i++)
        board[i] = tmpboard[i];
}

int abs(int x)
{
    if (x > 0)
        return x;
    else
        return -x;
}

void calculate_trans()
{
    for (int i = 1; i <= m * n; i++)
        for (int j = 1; j <= m * n; j++)
        {
            trans.a[i][j] = 0;
            if (occ[i] || occ[j])
                continue;
            int x1 = (i - 1) / m, y1 = i - x1 * m;
            int x2 = (j - 1) / m, y2 = j - x2 * m;
            if (abs(x1 - x2) + abs(y1 - y2) <= 1)
                trans.a[i][j] = 1;
        }
}

int main()
{
    scanf("%d%d%d", &n, &m, &q);
    int last = 1;
    board[1] = 1;
    calculate_trans();
    for (int i = 1; i <= q; i++)
    {
        int tp, x, y, t;
        cin >> tp >> x >> y >> t;
        calculate_now(t - last);
        if (tp == 1)
            cout << board[m * (x - 1) + y] << endl;
        else
            if (tp == 2)
            {
                occ[m * (x - 1) + y] = 1;
                board[m * (x - 1) + y] = 0;
                calculate_trans();
            }
            else
            {
                occ[m * (x - 1) + y] = 0;
                board[m * (x - 1) + y] = 0;
                calculate_trans();
            }
        last = t;
    }
    return 0;
}

