int root[N], size[N], m, n, x, y, sum[N], depth[N], lca[logN + 1][N], p;
ll cur, sk[N];
vector< int > v[N];

void init(int node, int root) {
	sum[node] = 1;
	lca[0][node] = root;
	foreach(it, v[node]) {
		if(*it == root) continue;
		depth[*it] = depth[node] + 1;
		init(*it, node);
		sk[node] += sum[*it] * (ll) sum[*it];
		sum[node] += sum[*it];
	} cur += (sum[node] - 1) * (ll) (n - sum[node]);	
	cur += ((sum[node] - 1) * (ll) (sum[node] - 1) - sk[node]) / 2;
}

int LCA(int x, int y) {
	if(depth[x] < depth[y]) swap(x, y);
	int diff = depth[x] - depth[y];
	FOR(i, 0, logN)
		if(diff & (1 << i))
			x = lca[i][x];
	if(x == y) return x;
	ROF(i, logN, 0)
		if(lca[i][x] != lca[i][y])
			x = lca[i][x],
			y = lca[i][y];
	return lca[0][x];
}

int findset(int x) { return root[x] = root[x] == x ? x : findset(root[x]); }

int up(int x) { return findset(lca[0][findset(x)]); }

int merge_up(int x) {
	x = findset(x);
	int y = up(x);	
	cur += (sum[x] * (ll) sum[x] - sk[x] - size[x]) / 2 * size[y];
	cur += ((n - sum[x]) * (ll) (n - sum[x]) - (sk[y] - sum[x] * (ll) sum[x] + (n - sum[y]) * (ll) (n - sum[y])) - size[y]) / 2 * size[x];
	sk[y] = sk[y] - sum[x] * (ll) sum[x] + sk[x]; 
	root[x] = y;
	size[y] += size[x];
	return y;
}

