struct BD{int v,c;}p[maxn];
bool cmp1(const BD &a,const BD &b){return a.v==b.v?a.c>b.c:a.v<b.v;}

struct line
{
    LL k,b;
    line (const LL &kk=0,const LL &bb=0){k=kk,b=bb;}
    LL calc()
    {return (e-b-1)/k+1;}
}l[maxn];
LL w[maxn];

void init()
{
    readi(n);readll(e);
    for(int i=1;i<=n;i++)
        readi(p[i].v),readi(p[i].c);
