    }



    std::vector<int> lim(n + 1);

    int v = 0, res = n;

    for (int i = 0; i <= n; i++) {

        v += i * c[i];

        res -= c[i];

        lim[i] = v + res * i;

    }



    std::vector dp(n + 1, std::vector<Z>(n + 1));

    dp[0][0] = 1;

    for (int x = n; x; x--) {

        for (int i = 0; i + x <= n; i++) {

