typedef pair<int, int> PII;

const int INF = 0x7f7f7f7f;
const PII END(INF, INF);

template <class Dis>
struct Record {
	Dis arr[NUML];

	inline Dis & operator [] (int i) {
		return arr[i];
	}

	inline void operator = (const Record<Dis> & other) {
		memcpy(arr, other.arr, sizeof(arr));
	}
};

int n, m;
string base[MAXN];
int seq[MAXN];
char aim[MAXN + 1];
char line[1000001];

vector<Record<int> > baseNext[MAXN];
Record<PII> seqNext[MAXN];

inline PII getNext(PII cur, char ch) {
	int j = baseNext[seq[cur.first]][cur.second][ch - 'a'];
	if (j == INF) {
		if (cur.first == m - 1) {
			return END;
		} else {
			return seqNext[cur.first + 1][ch - 'a'];
		}
	} else {
		return PII(cur.first, j);
	}
}

PII bestAns[MAXN + 1];

int main() {
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%s", line);
		base[i] = line;
	}
	scanf("%d", &m);
	for (int i = 0; i < m; i++) {
		scanf("%d", &seq[i]);
		seq[i]--;
	}
	scanf("%s", aim);

	for (int i = 0; i < n; i++) {
		baseNext[i].resize(base[i].size() + 1);
		memset(baseNext[i][base[i].size()].arr, 0x7f, sizeof(baseNext[i][base[i].size()].arr));
		for (int j = (int) base[i].size() - 1; j >= 0; j--) {
			baseNext[i][j] = baseNext[i][j + 1];
			baseNext[i][j][base[i][j] - 'a'] = j + 1;
		}
	}
	for (int i = m - 1; i >= 0; i--) {
		if (i == m - 1) {
			memset(seqNext[i].arr, 0x7f, sizeof(seqNext[i].arr));
		} else {
			seqNext[i] = seqNext[i + 1];
		}
		for (int j = 0; j < NUML; j++) {
			if (baseNext[seq[i]][0][j] != INF) {
				seqNext[i][j] = PII(i, baseNext[seq[i]][0][j]);
			}
		}
	}

	int len = strlen(aim);
	memset(bestAns, 0x7f, sizeof(PII) * (len + 1));
	bestAns[0] = PII(0, 0);
	for (int i = 0; i < len; i++) {
		for (int j = i; j >= 0; j--) {
			if (bestAns[j] != END) {
				PII cur = getNext(bestAns[j], aim[i]);
				bestAns[j + 1] = min(bestAns[j + 1], cur);
			}
		}
	}
	int ans;
	for (ans = len; bestAns[ans] == END; ans--);
	printf("%d\n", ans);

	return 0;
}

