	}

	int fnd(int x)

	{

		if(x==fa[x]) return x;

		int f=fa[x];

		fa[x]=fnd(fa[x]);

		v[x]^=v[f];

		return fa[x];

	}

	inline void mrg(int x,int y,int k)

	{

		//printf("mrg: x:%d y:%d k:%d\n",x,y,k);

		int fx=fnd(x),fy=fnd(y),t=v[x]^v[y]^k;

