  mem = hp2.malloc(N, mem);
  hp1.init(N);
  hp2.init(N);

  rep(i,N) heap_update(i);
  rep(i,T){
    k = hp1.hp[0];
    bet[k]++;
    res += -hp1.val[k];
    heap_update(k);
  }

  while(Q--){
    reader(&x,&y); y--;
    if(bet[y]) res -= P[y] * min(0.5, bet[y] / (double)(L[y]+bet[y]));
    if(x==1) L[y]++;
    if(x==2) L[y]--;
    if(bet[y]) res += P[y] * min(0.5, bet[y] / (double)(L[y]+bet[y]));

    heap_update(y);

    for(;;){
      if(hp2.size==0) break;
      i = hp1.hp[0];
      j = hp2.hp[0];

//      printf("---- "); writerLn(i,j);
//      printf("---- "); writerLn(-hp1.val[i],hp2.val[j]);

