int calc(int x) {

    int l = 1, r = x * 2, res = 0;

    while(l <= r) {

        int mid = (l + r) >> 1;

        LL a = mid / 2, b = mid - a;

        if(a * b >= x) res = mid, r = mid - 1;

        else l = mid + 1;

    }

    return res;

}

