            f[j] += f[j - i], f[j] %= mod;

    }

    for(int i = 0; i <= n; i++)

        for(int j = 0; i + j <= n; j++)

            g[i + j] += 1LL * f[i] * f[j] % mod, g[i + j] %= mod;

    memcpy(f, g, sizeof(f)); memset(g, 0, sizeof(g));

    for(int i = 0; i <= n; i++)

