typedef long long ll;
const int N = 210;
const ll mod = 1000000007LL;
int n, k;
int dp[N][N][2];
int vis[N][N][2], cs = 1;
int nxt[N], c[N];
int solve(int pos,int sum,int b)
{
    if(pos == n){
        return sum == 0;
    }
    int &ans = dp[pos][sum][b];
    if(vis[pos][sum][b] == cs)
        return ans;
    vis[pos][sum][b] = cs;
    ans = 0;
    if(sum%k == 0 && b)
    {
        ans = solve(pos+1, sum, b);
    }
    if(sum > 0){
        if((sum-1)%k == 0)
            ans = (ans + solve(pos+1, sum-1, 1)) % mod;
        else if(nxt[pos]!=-1)
            ans = (ans + solve(nxt[pos], sum-1, 0)) % mod;

        if(!b && nxt[pos]!=-1)
            ans = (ans + solve(nxt[pos], sum, b)) % mod;
    }
    return ans;
}
int best(int pos,int sum)
{
    if(pos == n){
        if(sum != 0)
            return -mod;
        return 0;
    }
    int &ans = dp[pos][sum][0];
    if(vis[pos][sum][0] == cs)
        return ans;
    vis[pos][sum][0] = cs;
    ans = -mod;
    if(sum == 0)
    {
        ans = best(pos+1, sum);
    }
    if( sum == k-1)
    {
        ans = max(ans, 1+best(pos+1, 0));
    }else if(nxt[pos]!=-1)
        ans = max(ans, 1+best(nxt[pos], sum+1));
    if(nxt[pos]!=-1 && sum != 0)
        ans = max(ans, best(nxt[pos], sum));
    return ans;
}
