inline void update(int o)
{
	tr[o] = std::max(tr[o << 1], tr[o << 1 | 1]);
}
inline void pushdown(int o)
{
	if (tag[o])
	{
		tr[o << 1] += tag[o];
		tag[o << 1] += tag[o];
		tr[o << 1 | 1] += tag[o];
		tag[o << 1 | 1] += tag[o];
		tag[o] = 0; 
	}
}
void modify(int o, int l, int r)
{
	if (ql <= l && r <= qr)
	{
		tr[o] += qv;
		tag[o] += qv;
		return ;
	}
	pushdown(o);
	int mid = l + r >> 1;
	if (ql <= mid) modify(o << 1, l, mid);
	if (mid < qr) modify(o << 1 | 1, mid + 1, r);
	update(o);
}
