ll rem(ll x) {
	ll now = 0;
	for (int i = dlen - 1; i >= 0; --i) {
		now *= MD;
		d[i] += now;
		now = d[i] % x;
		d[i] /= x;
	}
	while (dlen > 0 && d[dlen - 1] == 0)
		--dlen;
	return now;
}

ll get() {
	ll ans = 0;
	for (int i = dlen - 1; i >= 0; --i) {
		ans = (ans * MD + d[i]);
		if (ans >= MAXN) {
			cout << 0 << "\n";
			exit(0);
		}
	}
	return ans;
}

