	int slen = strlen(ss);
	reverse(ss, ss + slen);
	int k = 0;
	for (int i = 0; i < slen; i += 9) {
		ll now = 0;
		for (int j = min(slen - 1, i + 8); j >= i; --j)
			now = (now * 10 + ss[j] - '0');
		d[k++] = now;
	}
	dlen = k;
