const int maxn = 100005;

int n;
int A[maxn] = {0};
int Ans = 0;
int Last[maxn] = {0};

void Init()
{
	register int i, j, k;
	read(n);
	for (i = 1; i <= n; ++i) read(A[i]);
	memset(Last, -1, sizeof(Last));
}

void Solve()
{
	register int cnt;
	register int i, j, k;
	register int l, r;
	l = r = 1;
	cnt = 1;
	Last[A[1]] = 1;
	while (r <= n)
	{
		if (Last[A[r]] == -1)
		{
			++cnt;
		}
		Ckmax(Last[A[r]], r);
		while (cnt > 2)
		{
			if (Last[A[l]] == l)
			{
				Last[A[l]] = -1;
				--cnt;
			}
			++l;
		}
		Ckmax(Ans, r - l + 1);
		++r;
	}
}

void Put()
{
	write(Ans); putchar('\n');
}

int main()
{
	Init();
	Solve();
	Put();
	return 0;
}

