    vector<int> d(n);
    int last = INT_MAX;
    for (int i = n - 1; i >= 0; i--) {
        if (last == a[i])
            d[i] = d[i + 1];
        else {
            last = a[i];
            d[i] = i;
        }
    }

    vector<int> p[2];
