        dp[i] = vector<int>(n, 1);
        p[i] = vector<int>(n, 1);
        for (int j = 1; j < n; j++)
            p[i][j] = modsum(p[i][j - 1] + dp[i][j]);
    }
    ll answer = 0LL;
    answer = modsum(answer + l % mod);
    for (int i = 1; i < k; i++) {
        int cur = i % 2;
        int opp = 1 - cur;
        for (int j = 0; j < n; j++)
            dp[cur][j] = p[opp][d[j]];
        p[cur][0] = dp[cur][0];
        for (int j = 1; j < n; j++)
            p[cur][j] = modsum(p[cur][j - 1] + dp[cur][j]);
        answer = modsum(answer + (ff(t, i + 1) % mod * p[cur].back()) % mod);
        if (answer < 0) {
            answer++;
        }
        if (t >= i)
            for (int j = 0; j < b.size(); j++)
                answer = modsum(answer + p[opp][upper_bound(a.begin(), a.end(), b[j]) - a.begin() - 1]);
