        a[i]=lower_bound(V.begin(),V.end(),a[i])-V.begin()+1;

        last[a[i]]=i;

        if(first[a[i]]==0) first[a[i]]=i;

        suf[a[i]]++;

    }



    int ans=0;



    for(int i=1;i<=n;++i){

        if(first[a[i]]==i){

            if(last[a[i]-1]<i) maximize(F[i],F[last[a[i]-1]]+1);

            maximize(F[i],pre[a[i]-1]+1);

        }

