const int MOD = 1000000007;
const char nl = '\n';
const int MX = 200001; 

int dist[MX];
int A[MX];
set<pi> rem;
pqg<pi> q;

void add(int p, int pre, bool ty) {
    auto it1 = rem.lb({p, -1});
    if (it1 != rem.end()) {
        int v = it1->s;
        int d = max(pre, abs(A[v]-p));
        if (ty) {
            d = pre + abs(A[v]-p);
        }
        if (d < dist[v]) {
            dist[v] = d;
            q.push({d, v});
        }
    }
    if (it1 != rem.begin()) {
        it1--;
        int v = it1->s;
        int d = max(pre, abs(A[v]-p));
        if (ty) {
            d = pre + abs(A[v]-p);
        }
        if (d < dist[v]) {
            dist[v] = d;
            q.push({d, v});
        }
    }
}

void push(int p, int K) {
    while (rem.lb({p, -1}) != rem.end() && rem.lb({p, -1})->f <= p+K) {
        int x = rem.lb({p, -1})->s;
        rem.erase({A[x], x});
        q.push({K, x});
        dist[x] = K;
    }
    auto it = rem.lb({p, -1});
    while (it != rem.begin()) {
        it--;
        if (it->f < p-K) break;
        int x = it->s;
        rem.erase({A[x], x});
        q.push({K, x});
        dist[x] = K;
        it = rem.lb({p, -1});
    }
}


void solve() {
    int N, Q; cin >> N >> Q;
    F0R(i, N) dist[i] = 100000000;
    int S; cin >> S; S--;
    int D; cin >> D;
    F0R(i, N) {
        cin >> A[i];
        if (i != S) rem.ins({A[i], i});
    }
    dist[S] = 0;
    add(A[S]+D, 0, true);
    add(A[S]-D, 0, true);
    bool vis[MX]; F0R(i, N) vis[i] = false;
    while (!q.empty()) {
        int v = q.top().s;
        int d = q.top().f;
        q.pop();
        if (vis[v]) continue;
        vis[v] = true;
        //dbg(v, d);
        rem.erase({A[v], v});
        add(A[v], d, true);
        push(A[v]+D, d);
        push(A[v]-D, d);
        add(A[v]+D, 0, true);
        add(A[v]-D, 0, true);
    }
    /*F0R(i, N) {
        cout << dist[i] << " ";
    }
    cout << nl;*/

    while(Q--) {
        int X, V; cin >> X >> V; X--;
        cout << (dist[X]<=V?"Yes":"No") << nl;
    }
}

