        for(int i=0;i<SQRTN;i++){

            for(int j=0;j<=i;j++){

                if(j==0 || j==i)binom[i][j]=1;

                else binom[i][j]=(binom[i-1][j]+binom[i-1][j-1])%m;

            }

        }

    }

