template <const int mod, const int maxf> struct NTT {
    int pw;
    int fpow(int a, int k) {
        if (!k)
            return 1;
        int res = a, tmp = a;
        k--;
        while (k) {
            if (k & 1) {
                res = (long long)res * tmp % mod;
            }
            tmp = (long long)tmp * tmp % mod;
            k >>= 1;
        }
        return res;
    }
    int prt() {
        vector<int> dvs;
        for (int i = 2; i * i < mod; i++) {
            if ((mod - 1) % i)
                continue;
            dvs.push_back(i);
            if (i * i != mod - 1)
                dvs.push_back((mod - 1) / i);
        }
        for (int i = 2; i < mod; i++) {
            int flag = 1;
            for (int j = 0; j < dvs.size(); j++) {
                if (fpow(i, dvs[j]) == 1) {
                    flag = 0;
                    break;
                }
            }
            if (flag)
                return i;
        }
        assert(0);
        return -1;
    }
    NTT() { pw = prt(); }
    void dft(int a[], int pw, int n) {
        for (int m = n, h; h = m / 2, m >= 2;
                pw = (long long)pw * pw % mod, m = h) {
            for (int i = 0, w = 1; i < h; i++, w = (long long)w * pw % mod) {
                for (int j = i; j < n; j += m) {
                    int k = j + h, x = a[j] - a[k];
                    a[j] += a[k];
                    a[j] -= a[j] >= mod ? mod : 0;
                    a[k] = (long long)w * (x + mod) % mod;
                }
            }
        }
        for (int i = 0, j = 1; j < n - 1; j++) {
            for (int k = n / 2; k > (i ^= k); k /= 2)
                ;
            if (j < i)
                swap(a[i], a[j]);
        }
    }
    int fa[maxf], fb[maxf], fc[maxf];
    void multiply(int a[], int b[], int na, int nb, int c[]) {
        int n = na + nb - 1;
        while (n != (n & -n))
            n += n & -n;
        for (int i = na; i < n; i++)
            fa[i] = 0;
        for (int i = nb; i < n; i++)
            fb[i] = 0;
        int pwn = fpow(pw, (mod - 1) / n);
        dft(fa, pwn, n), dft(fb, pwn, n);
        for (int i = 0; i < n; i++)
            fc[i] = (long long)fa[i] * fb[i] % mod;
        dft(fc, fpow(pwn, mod - 2), n);
        int in = fpow(n, mod - 2);
        for (int i = 0; i < n; i++)
            fc[i] = (long long)fc[i] * in % mod;
    }
    vector<int> multiply(vector<int> a, vector<int> b) {
        int na = a.size(), nb = b.size();
        for (int i = 0; i < na; i++)
            fa[i] = a[i];
        for (int i = 0; i < nb; i++)
            fb[i] = b[i];
        multiply(fa, fb, na, nb, fc);
        int k = na + nb - 1;
        vector<int> res(k);
        for (int i = 0; i < k; i++)
            res[i] = fc[i];
        return res;
    }
};

const int mod = 998244353;  // 2^20 * 476 + 1
const int maxf = 1 << 22;
int n;
NTT <mod, maxf > ntt;

void add(int &a, int b) {
    a += b;
    if (a >= mod) a -= mod;
}

void process(void) {
    int n; cin >> n;
    vector <int> a(n), b(n), c(n); cin >> a >> b >> c;
    Vec <int, 3> dp(2, n + 1, n + 1);
    Vec <int, 2> sum_left(n, n), sum_right(n, n);
    add(sum_left[0][0], a[0]);
    add(sum_right[0][0], b[0]);
    dp[1][1][0] = 1;
    for (int i = 1; i < n; ++i) {
        int cur = i & 1;
        for (int j = 0; j <= i; ++j) for (int k = max(0, j - 1); k < i; ++k) if (dp[cur][j][k]) {
            add(dp[!cur][j + 1][k + 1], dp[cur][j][k]);
            add(dp[!cur][j][k], 1LL * dp[cur][j][k] * (k + 1) % mod);
            add(dp[!cur][j][k + 1], 1LL * dp[cur][j][k] * (i - k - 1) % mod);
            add(sum_left[i][k], 1LL * a[j] * dp[cur][j][k] % mod);
            add(sum_right[i][i - k - 1], 1LL * b[j] * dp[cur][j][k] % mod);
            dp[cur][j][k] = 0;
        }
    }
    vector <int> fact(n + 1), ifact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = 1LL * fact[i - 1] * i % mod;
    ifact[n] = 1LL * ntt.fpow(fact[n], mod - 2) % mod;
    for (int i = n; i > 0; --i) ifact[i - 1] = 1LL * ifact[i] * i % mod;
    vector <int> res(n + 1);
    vector <int> fa(2 * n * n), fb(2 * n * n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < max(i, 1); ++j) {
            if (i) fa[i * n * 2 + j] = 1LL * sum_left[i][j] * ifact[i] % mod;
            fb[i * n * 2 + j] = 1LL * sum_right[i][j] * ifact[i] % mod;
        }
    }
    vector <int> fc = ntt.multiply(fa, fb);
    for (int sz = 1; sz <= n; ++sz) {
        for (int i = 0; i < sz; ++i) {
            add(res[sz], 1LL * a[0] * sum_right[sz - 1][i] % mod * c[i] % mod);
            add(res[sz], 1LL * fc[(sz - 1) * n * 2 + i] * c[i + 1] % mod * fact[sz - 1] % mod);
        }
    }
    for (int i = 1; i <= n; ++i) cout << res[i] << ' ';
}

