#define _sz 5005
ll F[_sz],R[_sz];
void make(){
	F[0] = 1;
	for(int i=1;i<_sz;i++) F[i] = F[i-1]*i%mod;
	R[_sz-1] = modpow(F[_sz-1], mod-2);
	for(int i=_sz-2;i>=0;i--) R[i] = R[i+1] * (i+1) % mod;
}
ll C(int a,int b){
	if(b < 0 || a < b) return 0;
	return F[a]*R[b]%mod*R[a-b]%mod;
}

void solve(){
	int n;
	cin>>n;
	string a; string b; cin >> a >> b;
	rep(i, n) if(i%2 == 1 and a[i] != '?'){
		a[i] = (a[i]=='0'?'1':'0');
	}
	rep(i, n) if(i%2 == 1 and b[i] != '?'){
		b[i] = (b[i]=='0'?'1':'0');
	}
	int cnt[2][3] = {};
	//o(a); o(b);
	rep(i, n){
		if(a[i] == '0') cnt[0][0] ++;
		else if(a[i] == '1') cnt[0][1]++;
		else cnt[0][2]++;
	}
	rep(i, n){
		if(b[i] == '0') cnt[1][0]++;
		else if(b[i] == '1') cnt[1][1]++;
		else cnt[1][2] ++;
	}
	int zan = 0, free = 0, ans = 0;
	rep(i, n){
		int zan2 = 0, free2 = 0;
		rep(j, n){
			if(a[i] != '0' and b[j] != '0'){
				int x = free, y = free2, aa = zan-zan2;
				//(x+y) choose (y-a)


				//cout << i << j << x << y << aa << endl;
				if(0 <= y-aa and y-aa <= x+y){
					int tmp = C(x+y, y-aa);

					x = cnt[0][2] - x - (a[i] == '?');
					y = cnt[1][2] - y - (b[j] == '?');
					aa = (cnt[0][1]-zan-(a[i]=='1')) - (cnt[1][1]-zan2-(b[j]=='1'));
					//cout << x << y << aa << endl;
					if(0 <= y-aa and y-aa <= x+y){
						int tmp2 = C(x+y, y-aa);
						//cout<<i<<" "<<j<<" "<<tmp<<" "<<tmp2<<endl;
						tmp = tmp * tmp2 % mod * abs(i-j) % mod;
						ans += tmp;
					}
				}
			}
			if(b[j] == '1') zan2 ++;
			else if(b[j] == '?') free2++;
		}
		if(a[i] == '1') zan ++;
		else if(a[i] == '?') free ++;
	}
	o((ans%mod+mod)%mod);
}
