#include <bits/stdc++.h>
typedef long long ll;
using namespace std;

const int maxn = 3005;

ll n, m, k;
char s[2005][2005];
int L[2005], R[2005], U[2005], D[2005];

int mx[2005*4], lz[2005*4];
#define mid ((l+r)>>1)
#define ls (u<<1)
#define rs (u<<1|1)
void build(int u,int l,int r){
    mx[u] = lz[u] = 0;
    if(l == r) return;
    build(ls, l, mid); build(rs, mid+1, r);
}
inline void pushdown(int u){
    if(lz[u]){
        mx[ls] += lz[u], lz[ls] += lz[u];
        mx[rs] += lz[u], lz[rs] += lz[u];
        lz[u] = 0;
    }
}
void update(int u,int l,int r,int L,int R,int x){
    if(L<=l&&r<=R){
        mx[u] += x;
        lz[u] += x;
        return;
    }
    pushdown(u);
    if(L<=mid) update(ls,l,mid,L,R,x);
    if(R>mid) update(rs,mid+1,r,L,R,x);
    mx[u] = max(mx[ls], mx[rs]);
}
struct node{
    int L, R, flag, t;
    bool operator < (const node &b) const{
        return t < b.t;
    }
};
vector<node> v;
int main()
{
    scanf("%lld%lld", &n, &k);
    for(int i = 1; i <= n; i++) scanf("%s", s[i]+1);
    int kon = 0;
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            if(s[i][j] == 'B'){
                if(!L[i]) L[i] = j;
                R[i] = j;
            }
        }
        if(L[i] == 0) kon++;
        int TL = L[i], TR = R[i];
        L[i] = max(1ll,TR - k + 1);
        R[i] = TL;
        if(L[i] > R[i]) L[i] = R[i] = 0;
    }
    for(int i = 1; i <= n; i++){
        for(int j = 1; j <= n; j++){
            if(s[j][i] == 'B'){
                if(!U[i]) U[i] = j;
                D[i] = j;
            }
        }
        if(U[i] == 0) kon++;
        int TU = U[i], TD = D[i];
        U[i] = max(1ll, TD - k + 1);
        D[i] = TU;
        if(U[i] > D[i]) U[i] = D[i] = 0;
        else{
            v.push_back({max(1ll,i-k+1), i, 1, U[i]});
            v.push_back({max(1ll,i-k+1), i, -1, D[i]+1});
        }
    }
    sort(v.begin(), v.end());
    build(1,1,n);
    int ans = 0, pos = 0;
    for(int i = 1; i < k; i ++){
        if(L[i])
            update(1,1,n,L[i],R[i],1);
    }
    for(int i = k; i <= n; i++){
        if(L[i])
            update(1,1,n,L[i],R[i],1);
        if(L[i-k])
            update(1,1,n,L[i-k],R[i-k],-1);
        while(pos < v.size() && v[pos].t == i-k+1){
            update(1,1,n,v[pos].L, v[pos].R, v[pos].flag);
            pos++;
        }
        ans = max(ans, mx[1]);
    }
    printf("%d\n", ans + kon);
    return 0;
}

