namespace Main{
    const int MOD = 1e9 + 7;
    const int N = 200005;
    int t, n, m1, m2;
    ll f[N], fac[N], ifac[N];
    ll qpow(ll n, ll k){
        ll res = 1;
        while(k > 0){
            if(k & 1) res = res * n % MOD;
            n = n * n % MOD;
            k >>= 1;
        }
        return res;
    }
    ll binom(int n, int k){
        if(n < k) return 0;
        return fac[n] * ifac[n - k] % MOD * ifac[k] % MOD;
    }
    ll solve(const vector<int> &vec){
        ll ans = 1;
        for(int i = 0; i + 1 < vec.size(); i++){
            ans = ans * binom(vec[i + 1] - 2, vec[i] - 1) % MOD * fac[vec[i + 1] - vec[i] - 1] % MOD;
        }
        return ans;
    }
    void Main(){
        fac[0] = 1;
        for(int i = 1; i < N; i++) fac[i] = fac[i - 1] * i % MOD;
        ifac[N - 1] = qpow(fac[N - 1], MOD - 2);
        for(int i = N - 2; i >= 0; i--) ifac[i] = ifac[i + 1] * (i + 1) % MOD;
        input(t);
        while(t--){
            input(n, m1, m2);
            vector<int> pre(m1), suf(m2);
