inline int get(int r)
{
    int res = 0;
    for(; r >= 0; r = (r & (r + 1)) - 1)
    {
       res += t[r];
    }
    return res;
}

inline void upd(int pos)
{
    for(; pos < t.size(); pos |= pos + 1)
        t[pos]++;
}

inline int GetSubstNumber(vector<int> &numbers)
{
    int fact = 1, result = 0;
    t.assign(numbers.size(), 0);
    upd(numbers.back());
    for (int n = numbers.size() - 2; n >= 0; n--)
    {
        fact *= numbers.size() - n - 1;
        int pos = get(numbers[n] - 1);
        upd(numbers[n]);
        result += pos * fact;
    }
  return result;
}

