#include <bits/stdc++.h>
#define MAXN 200005

using namespace std;

int n,tot,head[MAXN]={0},dis[MAXN]={0};
int rv,ru,mx,ansx;
int a[MAXN];

struct edge{
	int to,next;
}e[MAXN<<1];

void add(int x,int y){
	tot++;
	e[tot].to=y;
	e[tot].next=head[x];
	head[x]=tot;
}

void dfs(int x,int fr,int dep){
	for(int p=head[x];p;p=e[p].next){
		int y=e[p].to;
		if(y==fr) continue;
		dfs(y,x,dep+1);
	}
	if(mx<dep){
		mx=dep;
		rv=x;
	}
}

bool frt(int u,int fr){
	if(u==rv) return true;
	for(int p=head[u];p;p=e[p].next){
		int v=e[p].to;
		if(v==fr)
			continue;
		if(frt(v,u)){
			dis[u]=0;
			return true;
		}
	}
	return false;
}

void flong(int u,int fr){
	if(dis[u]==-1){
		dis[u]=dis[fr]+1;
	}
	if(dis[u]>mx && u!=ru && u!=rv){
		mx=dis[u];
		ansx=u;
	}
	for(int p=head[u];p;p=e[p].next){
		int v=e[p].to;
		if(v==fr)
			continue;
		flong(v,u);
	}
}

int main(){
	int T;
	T=1;
	while(T--){
		scanf("%d", &n);
		tot=0;
		for(int i=1;i<n;i++){
			int f,g;
			scanf("%d %d", &f, &g);
			add(f,g);
			add(g,f);
		}
		mx=0;
		dfs(1,1,0);
		mx=0;
		ru=rv;
		dfs(ru,ru,0);
		int ans=mx;
		//ru,rv;
		memset(dis,-1,sizeof(dis));
		dis[rv]=0;
		dis[ru]=0;
		frt(ru,ru);
		mx=-1;
		flong(ru,ru);
		ans+=mx;
		printf("%d\n", ans);
		printf("%d %d %d\n", ru,rv,ansx);
	}
	return 0;
}

