struct Range {
	int left, right;
};

struct item {
	int key, prior, push;
	item * l, * r;
	item() { }
	item (int key, int prior) : key(key), prior(prior), push(0), l(NULL), r(NULL) { }

	void add() {
		++key;
		++push;
	}

	void do_push() {
		if (l) {
			l->key += push;
			l->push += push;
		}
		if (r) {
			r->key += push;
			r->push += push;
		}
		push = 0;
	}
};
typedef item * pitem;

int n;
vector<Range> ranges;
vector<item> items;

void split (pitem t, int key, pitem & l, pitem & r) {
	if (t) t->do_push();
	if (!t)
		l = r = NULL;
	else if (key <= t->key)
		split (t->l, key, l, t->l),  r = t;
	else
		split (t->r, key, t->r, r),  l = t;
}

void merge (pitem & t, pitem l, pitem r) {
	if (l) l->do_push();
	if (r) r->do_push();
	if (!l || !r)
		t = l ? l : r;
	else if (l->prior > r->prior)
		merge (l->r, l->r, r),  t = l;
	else
		merge (r->l, l, r->l),  t = r;
}

