int min_key(pitem t) {
	assert(t);
	t->do_push();
	if (t->l)
		return min_key(t->l);
	else
		return t->key;
}

int size(pitem t) {
	if (!t)
		return 0;
	t->do_push();
	return 1 + size(t->l) + size(t->r);
}

