  for (int i = 0; i < n; i++) {

  	auto& range = ranges[i];
  	pitem left = nullptr;
  	pitem middle = nullptr;
  	pitem right = nullptr;
  	split(root, range.left, left, middle);
  	split(middle, range.right, middle, right);

  	assert(left);

  	items[i] = item(range.left, rand());
  	pitem node = &items[i];

  	merge(left, left, node);

  	if (middle) {
  		middle->add();
  	}

  	if (right) {
  		pitem unused;
  		int remove = min_key(right);
  		split(right, remove + 1, unused, right);
  		assert(unused);
  	}

  	merge(left, left, middle);
  	merge(left, left, right);

  	root = left;
  }

  cout << (size(root) - 1) << endl;
  //cerr << solve_dumb() << endl;


  return 0;
}

