struct ft{

    vector <int> t;

    int sz = 0;

    ft(int n){

        t = vector <int> (n, 0);

        sz = n;

    }

    void inc(int pos, int d){

        for (pos; pos < sz; pos |= pos + 1){

            t[pos] += d;

        }

    }

    int get(int pos){

        int res = 0;

        for (pos; pos >= 0; pos = (pos & (pos + 1)) - 1){

            res += t[pos];

        }

        return res;

    }

};



void solve(int l, int r, int pl, int pr){

    if (l >= r) return;

    int mid = (l + r) >> 1;

    int cur = b[mid];

    pref[pl] = 0;

    for (int i = pl + 1; i < pr; ++i){

        pref[i] = pref[i - 1] + (a[i - 1] > cur);

    }

    suf[pr] = 0;

    for (int i = pr - 1; i >= pl; --i){

        suf[i] = suf[i + 1] + (a[i] < cur);

    }

    int pos = pl;

    int ans = inf;

    for (int i = pl; i < pr; ++i){

        if (pref[i] + suf[i] < ans){

            ans = pref[i] + suf[i];

            pos = i;

        }

    }

    p[mid] = pos;

    if (l + 1 < r){

        solve(l, mid, pl, pos + 1);

        solve(mid, r, pos, pr);

    }

}



