            dp[i][0] = merge(dp[i][0], {dp[j][k - 1].first + 1, dp[j][k - 1].second});
        }
        for (int j = 0; j < k - 1; j++) {
            if (dp[i][j].first > 0) {
            	val[c[i]][j + 1] = merge(val[c[i]][j + 1], {dp[i][j].first + 1, dp[i][j].second});
			}
       }
    }
    pair<int, int> ans = {0, 0};
    for (int i = 0; i <= n; i++) {
        ans = merge(ans, dp[i][k - 1]);
    }
    cout << ans.second << "\n";
}

