    for (auto& x : idxs) {

        cin >> x;

        --x;

    }



    vector<int> dist(n + 1, n + 1);

    dist[1] = 0;

    mask[1].set(0);

    queue<int> qu;

    qu.push(1);



    while (!qu.empty()) {

        auto v = qu.front();

        qu.pop();

        for (int i = 0; i < k; ++i)

        if (heroes[idxs[i]] == v) {

            for (int mt = 0; mt < (1 << k); ++mt) {

                if (mask[v].test(mt))

                    mask[v].set(mt | (1 << i));

            }

        }



        for (int ne : gr[v]) {

            if (dist[ne] > dist[v] + 1) {

                dist[ne] = dist[v] + 1;

                qu.push(ne);

            }

            if (dist[ne] == dist[v] + 1) {

                mask[ne] |= mask[v];

            }

        }

    }



    vector<int> cars;

    for (int i = 0; i < f; ++i)

        if (find(begin(idxs), end(idxs), i) == end(idxs))

            cars.push_back(heroes[i]);



    vector<int> ans(1 << k, 0);

    ans[0] = 1;

    for (int x : cars) {

        vector<int> nans = ans;

        for (int curmask = 0; curmask < (1 << k); ++curmask)

            if (mask[x][curmask]) {

                for (int p = 0; p < ans.size(); ++p)

                if (ans[p])

                    nans[p | curmask] = 1;

            }

        ans.swap(nans);

    }



    int best = 0;

    for (int curmask = 0; curmask < ans.size(); ++curmask)

    if (ans[curmask]) {

        int cur = 0;

        for (int t = 0; t < k; ++t)

            if (curmask & (1 << t))

                ++cur;

        best = max(cur, best);

    }

    cout << k - best << '\n';

    for (int i = 1; i <= n; ++i) {

        gr[i].clear();

        mask[i].reset();

    }

