ll inv[10100];
void deal(long long &ans, long long num, long long pr){
    for(int i = 0; i <= k; ++i){
        for(int j = 0;j <= num; ++j){
            f[i][j] = 0;
        }
    }
    f[0][num] = 1;
    for(int i = 0; i < k; ++i){
        for(int j = 0; j <= num; ++j){
            ll a = inv[j + 1] * f[i][j] % mod;
            f[i + 1][j] = (f[i + 1][j] + a) % mod;
        }
        for(int j = num - 1; j >= 0; --j){
            f[i + 1][j] = (f[i + 1][j + 1] + f[i + 1][j]) % mod;
        }
    }
    long long tmp = 1;
    long long sha = 0;
    for(int i = 0; i <= num; ++i){
        sha = (sha + tmp * f[k][i] % mod) % mod;
        tmp = tmp * pr % mod;

    }
    ans = ans * sha % mod;
}
