struct ArithmeticOperators {

  template <typename LowPriority = void>

  constexpr friend T operator+(T lhs, const T& rhs) { return lhs += rhs; }

  template <typename LowPriority = void>

  constexpr friend T& operator-=(T& lhs, const T& rhs) { return lhs += -rhs; }

  template <typename LowPriority = void>

