void factor_sieve() {

	lp[1] = 1;

	for (int i=2; i<MAX; ++i) {

		if (lp[i] == 0) {

			lp[i] = i;

			primes.push_back (i);

		}

		for (int j=0; j<primes.size() && primes[j]<=lp[i]; ++j) {

			int x = i * primes[j];

			if (x >= MAX) break;

			lp[x] = primes[j];

		}

	}

}



void pre_compute() {

	factors[1] = 0;

	for(int i=2; i<MAX; ++i) {

		if (lp[i] == i) {

			factors[i] = 1;

		}

		else {

			factors[i] = factors[i/lp[i]] + 1;

		}

	}

	for(int i=2; i<MAX; ++i) {

		prefix[i] = prefix[i-1] + factors[i];

	}

}



